// Adapter: the rule below is the same JavaScript as the recipe's n8n build.
// $('Step name') answers from this step's inputs: each is that step's output in this scenario.
const SOURCES = {"Config": "in0_Config", "Read the approval": "in1_Readtheapproval", "Read request at answer": "in2_Readrequestatanswer", "Read supplier record": "in3_Readsupplierrecord", "Read policy list": "in4_Readpolicylist"};
const LISTS = [];
const EXECUTED = [];
const DATA = {};
for (const [node, key] of Object.entries(SOURCES)) {
  const raw = input[key];
  let v = raw;
  if (typeof raw === 'string') { try { v = JSON.parse(raw); } catch (e) { v = raw; } }
  DATA[node] = LISTS.includes(node) ? (v || []).map(i => (i && i.json !== undefined ? i : { json: i })) : [{ json: v }];
}
const $ = (node) => {
  const ran = node in DATA || EXECUTED.includes(node);
  const list = () => { if (!(node in DATA)) throw new Error(`step ${node} has no data in this scenario`); return DATA[node]; };
  return { isExecuted: ran, first: () => list()[0], last: () => list()[list().length - 1], all: () => list(),
           get item() { return list()[0]; } };
};
const INPUT = "Read policy list";
const $input = { all: () => $(INPUT).all(), first: () => $(INPUT).first(), last: () => $(INPUT).last(), get item() { return $(INPUT).first(); } };
const $execution = { id: input.run_id };
// The webhook's fields, as the rule reads them in n8n: $('Step 9: Approval answered').first().json.body.
DATA["Step 9: Approval answered"] = [{ json: { body: { "approval_id": input.t_approval_id, "decision": input.t_decision, "by": input.t_by, "comment": input.t_comment } } }];
const BODIES = (out) => ({"key_q": encodeURIComponent('answer:' + $('Step 9: Approval answered').first().json.body.approval_id), "approval_q": encodeURIComponent($('Step 9: Approval answered').first().json.body.approval_id), "request_q": encodeURIComponent($('Read the approval').first().json.request_id), "answer_body": JSON.stringify({ status: $('Step 9: Approval answered').first().json.body.decision, decided_by: out.by, comment: $('Step 9: Approval answered').first().json.body.comment || '', decided_on: new Date().toISOString().slice(0, 10) }), "approved_body": JSON.stringify({ status: 'approved', locked: true, approved_by: out.by, approved_version: $('Read the approval').first().json.version }), "commitment_body": JSON.stringify({ id: $('Read the approval').first().json.request_id, request_id: $('Read the approval').first().json.request_id, budget_line: $('Read the approval').first().json.budget_line, amount: $('Read the approval').first().json.amount, billed: 0, remaining: $('Read the approval').first().json.amount }), "buyer_message": JSON.stringify({ to: $('Config').first().json.buyer, subject: 'Raise the PO: request ' + $('Read the approval').first().json.request_id, text: 'Approved by ' + out.by + ' for ' + $('Read the approval').first().json.amount + '; quote valid until ' + $('Read the approval').first().json.valid_until }), "blocked_body": JSON.stringify({ status: 'blocked', reasons: out.reasons }), "requester_message": JSON.stringify({ to: $('Read request at answer').first().json.requester, subject: 'Purchase request ' + $('Read the approval').first().json.request_id + ' blocked at release', text: 'Approved, but not released: ' + (out.reasons || []).join('; ') + '. Fix and raise it again.' }), "rejected_body": JSON.stringify({ status: 'rejected', rejected_by: out.by, rejection_comment: out.comment }), "done_body": JSON.stringify({ status: 'done', result: out.decision }), "log_body": JSON.stringify({ recipe: 'R11.3', item: $('Read the approval').first().json.request_id + ' v' + $('Read the approval').first().json.version, decision: out.decision, rules: out.rules }), "failed_body": JSON.stringify({ recipe: 'R11.3', item: $('Read the approval').first().json.request_id, reason: 'write failed', detail: 'Write after the approval answer failed; check the request, approval and commitment before rerunning', owner: $('Config').first().json.editor })});
const one = (r) => (Array.isArray(r) ? r : [r]).filter(Boolean).map(i => (i.json !== undefined ? i.json : i));
const $json = INPUT && INPUT in DATA ? $input.first().json : {};
const __rule = () => {
const iso = d => d.toISOString().slice(0, 10);
const day = s => new Date(String(s).slice(0, 10) + 'T00:00:00Z');
const today = day(iso(new Date()));
const addWorkingDays = (d, n) => { let x = new Date(d), k = 0; while (k < n) { x = new Date(x.getTime() + 86400000); if (x.getUTCDay() % 6 !== 0) k++; } return x; };
const same = (a, b) => String(a || '').trim().toLowerCase() === String(b || '').trim().toLowerCase();

// Steps 9 to 11: an answer counts only for an open approval of the request's current version.
const cfg = $('Config').first().json;
const ans = $('Step 9: Approval answered').first().json.body;
const appr = $('Read the approval').first().json;
const req = $('Read request at answer').first().json;
const supplier = $('Read supplier record').first().json;
const policy = $('Read policy list').first().json;
const by = ans.by || appr.approver;
const base = { approval: appr.id, version: appr.version, approver: appr.approver, answered_by: by,
  budget_before: appr.budget_before, budget_after: appr.budget_after };

if (appr.status !== 'open') return [{ json: { outcome: 'void', decision: `answer ignored: approval ${appr.status}`, rules: base } }];
if (Number(req.version) !== Number(appr.version)) {
  return [{ json: { outcome: 'void', decision: 'answer ignored: request changed since the approval started', rules: base } }];
}
if (ans.decision === 'rejected') {
  return [{ json: { outcome: 'rejected', decision: 'rejected', by, comment: ans.comment || '', rules: base } }];
}
if (ans.decision !== 'approved') return [{ json: { outcome: 'void', decision: `answer ignored: unknown decision ${ans.decision}`, rules: base } }];

// Step 9: rerun R11.2's supplier rule and its step 6 with the release margin; a waiver skips the quote half.
const reasons = [];
if (!supplier.active) reasons.push('supplier inactive');
if (supplier.hold) reasons.push('supplier on hold');
const waiver = req.waiver && (policy.waiver_grantors || []).includes(req.waiver.by) ? req.waiver : null;
if (!waiver) {
  const q = req.quote || {};
  const margin = addWorkingDays(today, cfg.release_margin_working_days);
  if (!q.valid_until || day(q.valid_until) < today) reasons.push('quote expired during approval');
  else if (day(q.valid_until) < margin) reasons.push('expires within release margin');
  if (!q.matches) reasons.push('quote not matched');
  if (!['stated', 'included'].includes(q.freight)) reasons.push('freight not stated');
}
const rules = Object.assign(base, { supplier: supplier.active && !supplier.hold ? 'passed' : 'failed',
  quote: waiver ? `waiver by ${waiver.by}` : (reasons.some(r => r.startsWith('quote') || r.startsWith('expires') || r.startsWith('freight')) ? 'failed' : 'passed'),
  reasons });
if (reasons.length) return [{ json: { outcome: 'blocked', decision: 'blocked', by, reasons, rules } }];
return [{ json: { outcome: 'release', decision: 'approved', by, rules } }];
};
const out = one(__rule())[0] || {};
return Object.assign({}, out, BODIES(out));
